  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #9aa8c3;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --error: #fca5a5;
      --error-bg: rgba(127, 29, 29, 0.22);
      --field-bg: rgba(15, 23, 42, 0.9);
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.2), transparent 34%),
        linear-gradient(180deg, #111827 0%, #020617 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border-radius: 20px;
      background: var(--panel);
      border: 1px solid var(--panel-border);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.8rem, 3vw, 2.3rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 700;
      font-size: 0.98rem;
    }

    input {
      width: 100%;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 12px;
      padding: 14px 16px;
      background: var(--field-bg);
      color: var(--text);
      font-size: 1rem;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #72809a;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16);
      transform: translateY(-1px);
    }

    .helper-text,
    .error-message {
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.3em;
      color: var(--error);
    }

    .form-field.invalid input {
      border-color: var(--error);
      background: var(--error-bg);
    }

    button {
      margin-top: 8px;
      border: 0;
      border-radius: 999px;
      padding: 14px 20px;
      font-size: 1rem;
      font-weight: 700;
      color: #03131b;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 14px 30px rgba(14, 165, 233, 0.3);
      filter: brightness(1.03);
    }

    button:focus-visible {
      outline: 3px solid rgba(125, 211, 252, 0.4);
      outline-offset: 3px;
    }

    .success-message {
      margin: 0;
      color: #86efac;
      min-height: 1.4em;
      font-weight: 700;
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact Support</h1>
    <p class="intro">Send us your details and our support team will follow up as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jordan Lee" required aria-describedby="full-name-error">
        <p id="full-name-error" class="error-message" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" placeholder="jordan@example.com" required aria-describedby="email-error">
        <p id="email-error" class="error-message" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="(555) 123-4567" aria-describedby="phone-helper phone-error">
        <p id="phone-helper" class="helper-text">Optional. Use a format such as (555) 123-4567 or 555-123-4567.</p>
        <p id="phone-error" class="error-message" aria-live="polite"></p>
      </div>

      <button type="submit">Submit</button>
      <p id="form-success" class="success-message" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const successMessage = document.getElementById("form-success");

    const fields = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }
          return "";
        }
      },
      email: {
        input: document.getElementById("email"),
        error: document.getElementById("email-error"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      phone: {
        input: document.getElementById("phone"),
        error: document.getElementById("phone-error"),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return "";
          }

          const phonePattern = /^(\+?\d{1,2}[\s-]?)?(\(\d{3}\)|\d{3})[\s-]?\d{3}[\s-]?\d{4}$/;
          if (!phonePattern.test(trimmed)) {
            return "Enter a valid phone number in the expected format.";
          }
          return "";
        }
      }
    };

    function setFieldState(fieldConfig, message) {
      const fieldWrapper = fieldConfig.input.closest(".form-field");
      fieldConfig.error.textContent = message;
      fieldWrapper.classList.toggle("invalid", Boolean(message));
      fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(fieldConfig) {
      const message = fieldConfig.validate(fieldConfig.input.value);
      setFieldState(fieldConfig, message);
      return !message;
    }

    Object.values(fields).forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("blur", () => {
        validateField(fieldConfig);
      });

      fieldConfig.input.addEventListener("input", () => {
        if (fieldConfig.error.textContent) {
          validateField(fieldConfig);
        }
        successMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      successMessage.textContent = "";

      const isFormValid = Object.values(fields).every((fieldConfig) => validateField(fieldConfig));

      if (!isFormValid) {
        const firstInvalidField = Object.values(fields).find((fieldConfig) => fieldConfig.error.textContent);
        if (firstInvalidField) {
          firstInvalidField.input.focus();
        }
        return;
      }

      successMessage.textContent = "Your support request is ready to send.";
      form.reset();
      Object.values(fields).forEach((fieldConfig) => setFieldState(fieldConfig, ""));
    });
  </script>
</body>
</html>
